input.sparql:
SELECT ?point ?ts WHERE {
  ?ahu brick:hasSubEntity ?point .
  ?ahu brick:hasIdentifier "AHU03" .
  ?point rdf:type brick:Electrical_Power .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?s ?o WHERE {
  ?s brick:hasIdentifier ?o .
  ?o a brick:Identifier .
} LIMIT 50

SELECT ?p ?ts ?cls WHERE {
  ?p ref:hasTimeseriesId ?ts .
  ?p rdf:type ?cls .
  FILTER(CONTAINS(str(?p), "AHU03") || CONTAINS(str(?p), "ahu03"))
}

